#include <Cellerator/compiler/ir/realization/implement_launch_and_synchronization_dependencies_v1.hh>
namespace cellerator::compiler::ir::realization::v1 {namespace{launch_dependency_status_v1 fail(launch_dependency_status_v1 s,std::string*e,const char*m)noexcept{if(e)*e=m;return s;}}
launch_dependency_status_v1 validate_launch_dependency_graph_v1(const launch_dependency_graph_v1&g,std::string*e)noexcept{for(const auto&d:g.dependencies){if(d.producer>=g.stage_count||d.consumer>=g.stage_count)return fail(launch_dependency_status_v1::invalid_stage,e,"dependency stage outside graph");if(d.producer>=d.consumer)return fail(launch_dependency_status_v1::cycle,e,"dependencies must follow topological stage order");if((d.kind==synchronization_kind_v1::readiness_token||d.kind==synchronization_kind_v1::event_wait)&&!valid(d.token))return fail(launch_dependency_status_v1::invalid_token,e,"event/readiness identity required");if(d.kind==synchronization_kind_v1::event_wait&&d.producer_stream==d.consumer_stream)return fail(launch_dependency_status_v1::redundant_wait,e,"same-stream wait must be elided");if(d.kind==synchronization_kind_v1::host_synchronize&&!d.explicit_host_sync)return fail(launch_dependency_status_v1::implicit_host_sync,e,"host synchronization must be explicit");if(d.kind==synchronization_kind_v1::device_link&&d.source_device==d.destination_device)return fail(launch_dependency_status_v1::invalid_link,e,"device link requires distinct devices");}if(e)e->clear();return launch_dependency_status_v1::valid;}
launch_dependency_graph_v1 elide_same_stream_waits_v1(const launch_dependency_graph_v1&g){launch_dependency_graph_v1 out{g.stage_count,{},g.same_stream_elisions};for(const auto&d:g.dependencies)if(d.kind==synchronization_kind_v1::event_wait&&d.producer_stream==d.consumer_stream)++out.same_stream_elisions;else out.dependencies.push_back(d);return out;}
} // namespace cellerator::compiler::ir::realization::v1
